// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amt) public {
        vm.assume(caller != address(0));

        uint256 seedFund = 1 ether;
        amt = bound(amt, 0, seedFund);

        vm.deal(address(this), seedFund);
        (bool okFund, ) = address(c).call{value: seedFund}("");
        require(okFund);

        assertEq(address(c).balance, seedFund);

        bool success;
        vm.deal(caller, 1 wei);
        vm.prank(caller);
        try c.withdraw(amt) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success == (caller == address(this)));
    }
}
